agent = create_agent("anthropic:claude-sonnet-4-5", tools=[search_policies, send_email],
    system_prompt="Answer only from retrieved policy text. Cite the policy name.",
    middleware=[HumanInTheLoopMiddleware(interrupt_on={"send_email": {"allowed_decisions": ["approve", "edit", "reject"]}})],
    checkpointer=InMemorySaver())

cfg = {"configurable": {"thread_id": "demo-1"}}
agent.invoke({"messages": [{"role": "user", "content": "Email asha@co.in our leave policy"}]}, cfg)
agent.invoke(Command(resume={"decisions": [{"type": "approve"}]}), cfg)  # same thread_id

judge = create_llm_as_judge(prompt=CORRECTNESS_PROMPT, model="anthropic:claude-sonnet-4-5", feedback_key="correctness")
def correctness(inputs, outputs, reference_outputs):
    return judge(inputs=inputs, outputs=outputs, reference_outputs=reference_outputs)
def target(inputs):
    out = agent.invoke({"messages": [{"role": "user", "content": inputs["question"]}]}, {"configurable": {"thread_id": str(uuid.uuid4())}})
    return {"answer": out["messages"][-1].content}
evaluate(target, data="hr-policy-qa", evaluators=[correctness], experiment_prefix="capstone-v1")
